import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { debounce } from 'lodash'
import { useCallback, useState } from 'react'
import { useHistory } from 'react-router'
import { Container } from '../../../../../../components'
import ProviderListComponent from '../../../components/ProviderList'
import ProviderWorkshopStyles, { ProviderWorkshopStyleWrapper } from './index.style'

const ProviderList = () => {
  // const [selectedProvider, setSelectedProvider] = useState(null)
  const [searchText, setSearchText] = useState()
  const [{ PROVIDER_LIST_LOADER }] = useLoaderContextValue()
  const history = useHistory()

  const handleSelect = useCallback(({ code, name }) => {
    history.push({
      pathname: `/providers/${code}/workshops/`,
      state: { providerName: name }
    })
  }, [history])

  return (
    <Container
      className='bg-white'
      loader={!!PROVIDER_LIST_LOADER}
      title='Bengkel Rekanan'
      onSearch={debounce(setSearchText, 500)}
      showSearchBar
      displayBackButton
    >
      <ProviderWorkshopStyleWrapper>
        <ProviderWorkshopStyles />
        <ProviderListComponent searchText={searchText} onSelect={handleSelect} />
      </ProviderWorkshopStyleWrapper>
    </Container>
  )
}
export default ProviderList
