import { DisplayFlexCCC } from '../../../../../commonStyle/index.style'
import { ProviderCardStyleWrapper } from './index.style'

const ProviderCard = ({ logoUrl, code, name, shortName, onSelect }) => {
  return (
    <ProviderCardStyleWrapper
      className='flex-container'
      onClick={() => {
        if (typeof onSelect === 'function') {
          onSelect({ code, name })
        }
      }}
    >
      <DisplayFlexCCC className='provider-logo'>
        <img src={logoUrl} alt='provider-logo' width='32px' />
      </DisplayFlexCCC>
      <div className='provider-title'>
        {shortName}
      </div>
    </ProviderCardStyleWrapper>
  )
}
export default ProviderCard
