import { useGet } from '@pasarpolis/common-react-hooks'
import { useEffect } from 'react'
import Alert from '../Alert'
import ProviderCard from '../ProviderCard'
import { apiConfig } from './constants'
import { connect } from 'react-redux'
import { ProviderListWrapper } from './index.style'

const ProviderList = ({ searchText, workshopName, showAlert = true, ...props }) => {
  const [providerListData, providerListRequest] = useGet(apiConfig.providerList)

  useEffect(() => {
    providerListRequest({
      product_code: 'car-protection',
      category: props.agentDetails.category,
      name: searchText || undefined,
      workshop_name: workshopName || undefined
    })
  }, [
    providerListRequest,
    searchText,
    workshopName
  ])

  return (
    <ProviderListWrapper>
      {
        showAlert && (
          <Alert
            message='Anda dapat mencari bengkel rekanan berdasarkan provider asuransi atau mencari langsung berdasarkan kota, provinsi, nama atau alamat bengkel.'
          />
        )
      }
      <div className='list-container'>
        {
          providerListData
            ?.map(({ logo_url: logoUrl, code, name, short_name: shortName }, index) => (
              <ProviderCard
                logoUrl={logoUrl}
                code={code}
                shortName={shortName}
                name={name}
                key={index}
                {...props}
              />
            ))
        }
      </div>
    </ProviderListWrapper>
  )
}
export default connect((state) => ({
  agentDetails: state.User.agentDetails
}))(ProviderList)
